from pathlib import Path
from html import escape
from urllib.parse import quote
import json
import re
import hashlib
from functools import cache
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://gabrielsantanabr.github.io/matriz/'
GITHUB = 'https://github.com/GabrielSantanaBR/'
LINKEDIN = 'https://www.linkedin.com/in/gabriel-santana-b3654622a/'
DESCRIPTION = 'Sistema financeiro, sites, sistemas para negócios e planilhas de controle. Conheça os quatro produtos da MATRIZ e peça uma proposta para a sua rotina.'
ALL_PROJECTS = json.loads((ROOT/'content/projects.json').read_text())
PROJECTS = [p for p in ALL_PROJECTS if p.get('listed', True)]
CASES = [p for p in ALL_PROJECTS if p.get('page')]
VISIBLE_CASES = [p for p in PROJECTS if p.get('page')]
FEATURED = [p for p in PROJECTS if p.get('featured')]
DATE = '2026-11-09'
CATALOG = json.loads((ROOT/'content/products.json').read_text())
PRODUCT_BY_ID = {p['id']:p for p in CATALOG}
SITE_ASSETS = {a['file']:a for a in json.loads((ROOT/'docs/site-asset-provenance.json').read_text())['assets']}

@cache
def asset(path):
    return path+'?v='+hashlib.sha256((ROOT/path).read_bytes()).hexdigest()[:12]

def contact_bundle():
    """Ship a single deferred script; keep the contact core importable in tests."""
    core=(ROOT/'assets/js/contact-core.js').read_text()
    ui=(ROOT/'assets/js/contact.js').read_text()
    assert ui.startswith('import {')
    script="// Generated by scripts/render.py from contact-core.js and contact.js.\n(() => {\n'use strict';\n"
    script+=re.sub(r'^export ', '', core, flags=re.MULTILINE)+'\n'+ui.split('\n',1)[1]+'\n})();\n'
    (ROOT/'assets/js/contact-bundle.js').write_text(script)

def e(s): return escape(str(s), quote=True)
def external(url, label, cls=''):
    name=re.sub(r'<[^>]+>','',label).replace('↗','').strip()
    return f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer" aria-label="{e(name)} (abre em nova aba)" class="{cls}">{label}</a>'
def repo_url(p): return GITHUB+p['repo']+('/tree/'+p['branch'] if p.get('branch') else '')
def brand(): return '<a class="brand" href="index.html" aria-label="MATRIZ — início"><img src="assets/brand/logo-matriz-96.webp" alt="" width="47" height="47" decoding="async"><strong itemprop="name">MATRIZ</strong></a>'
def action(href,label,primary=False): return f'<a class="button {"primary" if primary else "secondary"}" href="{e(href)}">{label}<span aria-hidden="true">↗</span></a>'
def nav(active):
    links=[('index.html#produtos','Produtos'),('repertoire.html','Exemplos'),('prices.html','Como contratar'),('index.html#duvidas','Dúvidas')]
    navlinks=''.join(f'<a href="{url}"'+(' aria-current="page"' if active==url else '')+f'>{label}</a>' for url,label in links)
    return f'''<a class="skip-link" href="#main-content">Pular para o conteúdo</a>
<header class="site-header"><div class="container header-inner">{brand()}
<button class="menu-toggle" type="button" aria-controls="main-nav" aria-expanded="false" aria-label="Abrir menu"><span>Menu</span><i aria-hidden="true"></i></button>
<nav class="main-nav" id="main-nav" aria-label="Navegação principal">{navlinks}<a class="mobile-contact" href="contact.html">Pedir proposta ↗</a></nav>
<a class="button header-cta" href="contact.html">Pedir proposta <span aria-hidden="true">↗</span></a></div></header>'''
def footer():
    products=''.join(f'<a href="{p["page"]}">{e(p["name"])}</a>' for p in CATALOG)
    return f'<footer class="site-footer"><div class="container"><div class="footer-top"><div class="footer-brand">{brand()}<p>Financeiro, sites, sistemas e planilhas.<br>Para quem cuida do próprio negócio.</p></div><div class="footer-links"><p class="label">Produtos</p>{products}</div><div class="footer-links"><p class="label">Conte com a MATRIZ</p><a href="prices.html">Como contratar</a><a href="repertoire.html">Ver exemplos</a><a href="contact.html">Pedir proposta</a>{external(LINKEDIN,"Gabriel Santana · LinkedIn ↗")}</div></div><div class="footer-bottom"><span>© <span id="year" data-year>2026</span> MATRIZ. Tecnologia aplicada.</span><nav class="footer-legal" aria-label="Informações legais"><a href="privacy.html">Privacidade</a><a href="security.html">Segurança</a></nav></div></div></footer>'
def write_page(path,title,description,body,*,noindex=False,contact=False):
    url=BASE+('' if path=='index.html' else path)
    csp="default-src 'self'; base-uri 'none'; object-src 'none'; frame-src 'none'; media-src 'none'; worker-src 'none'; font-src 'self'; img-src 'self'; style-src 'self'; script-src 'self'; connect-src "+("https://api.web3forms.com" if contact else "'none'")+"; form-action "+("https://api.web3forms.com" if contact else "'none'")+"; upgrade-insecure-requests"
    html=f'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="{csp}"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="theme-color" content="#0A0B0D"><meta name="color-scheme" content="dark"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><title>{e(title)}</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{url}">
<meta property="og:locale" content="pt_BR"><meta property="og:type" content="website"><meta property="og:site_name" content="MATRIZ"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/brand/matriz-share.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="MATRIZ — Seu negócio. Próximo nível. Sistema financeiro, sites, sistemas para negócios e planilhas de controle."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{BASE}assets/brand/matriz-share.png">
<meta name="twitter:image:alt" content="MATRIZ — Sistema financeiro, sites, sistemas para negócios e planilhas de controle."><link rel="icon" href="assets/brand/icon-32.png" type="image/png" sizes="32x32"><link rel="apple-touch-icon" href="assets/brand/icon-180.png" sizes="180x180"><link rel="preload" href="assets/fonts/space-grotesk-600.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="assets/fonts/inter-400.woff2" as="font" type="font/woff2" crossorigin><link rel="manifest" href="site.webmanifest"><link rel="stylesheet" href="{asset("assets/css/matriz.css")}"><script src="{asset("assets/js/site.js")}" defer></script>{f'<script src="{asset("assets/js/contact-bundle.js")}" defer></script>' if contact else ''}{f'<script src="{asset("assets/js/preview.js")}" defer></script>' if "data-preview" in body else ""}</head>
<body class="page-{'home' if path == 'index.html' else path.removesuffix('.html')}" itemscope itemtype="https://schema.org/Organization"><meta itemprop="url" content="{BASE}">{nav(path)}<main id="main-content" tabindex="-1">{body}</main>{footer()}{preview_dialog() if "data-preview" in body else ""}</body></html>'''
    if path=='404.html':
        # A Pages 404 is also served for arbitrarily nested URLs.
        import re
        html=re.sub(r'((?:href|src)=")(?!(?:https?:|#))([^\"]+)',lambda m:m[1]+'/matriz/'+m[2],html)
    (ROOT/path).write_text(html+'\n')

def architecture(p):
    boxes='<span aria-hidden="true">→</span>'.join(f'<b>{e(x)}</b>' for x in p['diagram'])
    return f'<div class="architecture-art"><div class="label">{e(p["name"])} / fluxo da solução</div><div class="architecture-flow">{boxes}</div><p>{e(" · ".join(p["stack"][:3]))}</p><div class="architecture-note">Diagrama de funcionamento</div></div>'
def responsive_image(p,*,sizes='(max-width: 680px) calc(100vw - 48px), 45vw',priority=False):
    image=p.get('image_webp',p.get('image'))
    candidates=[]
    for width in [480,960]:
        resized=str(Path(image).with_name(Path(image).stem+'-'+str(width)+'.webp'))
        if resized in SITE_ASSETS:candidates.append(f'{resized} {width}w')
    source_set=''
    if candidates:
        candidates.append(f'{image} {p["image_width"]}w')
        source_set=f' srcset="{e(", ".join(candidates))}" sizes="{e(sizes)}"'
    return f'<img src="{e(image)}"{source_set} alt="{e(p["image_alt"])}" width="{p.get("image_width",1440)}" height="{p.get("image_height",900)}" loading="{"eager" if priority else "lazy"}"'+(' fetchpriority="high"' if priority else '')+' decoding="async">'

def visual(p,**kwargs):
    if p.get('image'):return responsive_image(p,**kwargs)
    return architecture(p)

def preview_attrs(p):
    return f'data-preview data-preview-title="{e(p["name"])}" data-preview-alt="{e(p.get("image_alt",p["name"]))}" data-preview-caption="{e(p.get("image_note","Prévia do projeto."))}"'

def preview_dialog():
    return '''<dialog class="preview-dialog" id="preview-dialog" aria-labelledby="preview-title" aria-describedby="preview-caption"><div class="preview-header"><h2 id="preview-title">Prévia do projeto</h2><button class="preview-close" id="preview-close" type="button" autofocus>Fechar <span aria-hidden="true">×</span></button></div><div class="preview-stage" id="preview-stage" tabindex="0" role="region" aria-label="Imagem do projeto"><img id="preview-image" alt="" width="1440" height="900" decoding="async" hidden></div><p class="preview-load-status" id="preview-load-status" role="status" aria-live="polite"></p><div class="preview-footer"><p id="preview-caption"></p><div class="preview-actions"><button class="button secondary" id="preview-zoom" type="button" aria-pressed="false">Ampliar detalhes</button><a class="text-link" id="preview-original" href="assets/brand/logo-matriz.png" target="_blank" rel="noopener noreferrer">Abrir original <span aria-hidden="true">↗</span><span class="visually-hidden"> em nova aba</span></a></div></div></dialog>'''

def project_screenshots(p):
    if not p.get('image'): return ''
    images=[p]+p.get('gallery',[])
    return ''.join(f'''<figure class="case-screenshot"><a href="{e(item['image'])}" {preview_attrs({**item,'name':p['name']})} target="_blank" rel="noopener noreferrer" aria-label="Ampliar imagem de {e(p['name'])}">{responsive_image(item,sizes='(max-width: 960px) 90vw, (max-width: 1440px) calc(100vw - 420px), 1000px',priority=i==0)}</a><figcaption>{e(item.get('image_note','Captura real da interface do repositório.'))} <a class="expand-image" {preview_attrs({**item,'name':p['name']})} href="{e(item['image'])}" target="_blank" rel="noopener noreferrer">Ampliar imagem <span aria-hidden="true">↗</span><span class="visually-hidden"> de {e(p['name'])}</span></a></figcaption></figure>''' for i,item in enumerate(images))
def case_tile(p):
    name=p.get('card_title',p['name'])
    return f'''<article class="case portfolio-case" data-project-group="{e(p.get('group','gestao'))}"><a class="case-visual" href="{e(p['image'])}" {preview_attrs(p)} target="_blank" rel="noopener noreferrer" aria-label="Ampliar imagem de {e(name)}">{visual(p,sizes='(max-width: 680px) calc(100vw - 48px), 45vw')}<span class="case-image-hint" aria-hidden="true">Ampliar ⤢</span></a><h3>{e(name)}</h3><p class="case-summary">{e(p.get('card_summary',p.get('client_summary',p['summary'])))}</p><div class="case-card-footer"><p>{e(p.get('card_note',p.get('display_status',p['status'])))}</p><a class="text-link" href="{p['page']}">Ver detalhes<span class="visually-hidden"> de {e(name)}</span> <span aria-hidden="true">↗</span></a></div></article>'''
def cta(product=None, example=None):
    href=product_contact(product,example) if product else 'contact.html'
    return f'''<section class="contact-band"><div class="container"><div><h2 id="cta-title">Vamos conversar.</h2><p>Conte o que seu negócio precisa. Você recebe uma proposta antes de contratar.</p></div><div class="band-action">{action(href,'Pedir proposta',True)}</div></div></section>'''

def product_contact(product, example=None):
    if example:
        product={**product,'name':product['name']+' (exemplo: '+example+')'}
    return 'contact.html?service='+product['service']+'&project='+quote(product['name'])

def product_preview(product, *, priority=False):
    example=next(p for p in PROJECTS if p['repo']==product['example_repo'])
    return f'''<figure class="product-showcase"><a class="product-screen" href="{e(example['image'])}" {preview_attrs(example)} target="_blank" rel="noopener noreferrer" aria-label="Ampliar exemplo de {e(product['name'])}"><span class="product-screen-bar"><span>{e(product['visual_label'])}</span><span class="screen-expand">Ampliar <span aria-hidden="true">⤢</span></span></span><span class="product-screen-image">{visual(example,sizes='(max-width: 680px) calc(100vw - 48px), (max-width: 960px) 85vw, 55vw',priority=priority)}</span></a><figcaption><span>{e(product['example_caption'])}</span><a href="{example['page']}">Sobre este exemplo <span aria-hidden="true">↗</span></a></figcaption></figure>'''

def product_card(product):
    features=''.join(f'<li>{e(x)}</li>' for x in product['features'])
    return f'''<article class="catalog-product" data-product="{product['id']}" id="produto-{product['id']}" aria-labelledby="title-{product['id']}"><div class="catalog-product-copy"><div class="catalog-product-heading"><p class="product-kicker"><span>{CATALOG.index(product)+1:02d}</span>{e(product['eyebrow'])}</p><h3 id="title-{product['id']}"><a href="{product['page']}">{e(product['name'])}</a></h3><p class="catalog-pitch">{e(product['pitch'])}</p><p class="catalog-summary">{e(product['summary'])}</p></div><ul class="catalog-features">{features}</ul><div class="catalog-product-bottom">{action(product['page'],'Conhecer o produto')}<a class="text-link" href="{product_contact(product)}">Pedir proposta<span class="visually-hidden"> para {e(product['name'])}</span> <span aria-hidden="true">↗</span></a></div></div>{product_preview(product)}</article>'''

def product_index():
    return '<nav class="catalog-index" aria-label="Escolha o produto pela sua necessidade">'+''.join(f'''<a href="#produto-{p['id']}"><span class="catalog-index-number">0{i}</span><span><strong>{e(p['name'])}</strong><small>{e(p['purpose'])}</small></span><span class="catalog-index-arrow" aria-hidden="true">↓</span></a>''' for i,p in enumerate(CATALOG,1))+'</nav>'

def proposal_points():
    points=[('O que você recebe','Funcionalidades, formato de entrega e responsabilidades de cada parte.'),('Quanto custa manter','Valor do projeto e eventuais custos de domínio, hospedagem, licenças e manutenção.'),('Prazo e acompanhamento','Etapas de apresentação, validação e entrega, de acordo com o escopo.'),('Suporte, acessos e dados','Orientação de uso, condições de suporte e como ficam os acessos e os dados na entrega.')]
    return '<dl class="proposal-points">'+''.join(f'<div><dt>{title}</dt><dd>{description}</dd></div>' for title,description in points)+'</dl>'

def faq():
    items=[('Qual produto faz sentido para o meu negócio?','Financeiro para acompanhar o dinheiro; Sites para apresentar sua marca; Sistemas para organizar clientes, equipe e rotinas; Planilhas para controlar gastos, vendas ou custos. Uma solução simples pode ser suficiente para começar. A escolha considera sua rotina e quantas pessoas vão usar.'),('Quanto vou pagar? Tem mensalidade?','O orçamento é feito após definir o escopo. A proposta discrimina o valor da entrega e os custos recorrentes que existirem, como hospedagem, licenças ou manutenção. Não há contratação automática ao enviar o contato.'),('O que estou vendo já está pronto para o meu negócio?','As imagens apresentam projetos, propostas visuais e demonstrações em diferentes estágios. Cada exemplo informa sua condição. A configuração e os recursos da sua entrega são definidos na proposta.'),('Como ficam o suporte e as mudanças depois?','A proposta registra orientação de uso, suporte, acessos e como ficam seus dados na entrega. Manutenção contínua e novas funcionalidades são combinadas conforme a necessidade, com custos identificados.')]
    return '<div class="faq-list">'+''.join(f'<details class="faq-item"><summary>{question}<span aria-hidden="true"></span></summary><p>{answer}</p></details>' for question,answer in items)+'</div>'

def repertoire_rows():
    filters=''.join(f'<button class="filter-button" type="button" data-filter="{p["id"]}" aria-pressed="false">{e(p["name"])}</button>' for p in CATALOG)
    rows=''.join(f'<a class="repo-row" href="{repo_url(p)}" target="_blank" rel="noopener noreferrer" data-category="{p["product"]}" data-repo="{e(p["repo"])}"><h3>{e(p["name"])}</h3><p>{e(p["summary"])}</p><span class="repo-kind">{e(p["status"])}</span><span aria-hidden="true">↗</span></a>' for p in PROJECTS)
    return f'<div class="filter-bar"><div class="filters" role="group" aria-label="Filtrar referências por produto"><button class="filter-button" type="button" data-filter="Todos" aria-pressed="true">Todos</button>{filters}</div><p class="result-count" id="repo-count" aria-live="polite" role="status">{len(PROJECTS)} repositórios</p></div><div class="repertoire">{rows}</div>'

def portfolio_page():
    order=[repo for product in CATALOG for repo in product['examples']]
    cases=[next(p for p in PROJECTS if p['repo']==repo) for repo in order]
    groups=[('Todos','Todos os exemplos')]+[(p['id'],p['name']) for p in CATALOG]
    filters=''.join(f'<button class="filter-button" type="button" data-project-filter="{key}" aria-controls="portfolio-projects" aria-pressed="{str(key=="Todos").lower()}">{e(label)}</button>' for key,label in groups)
    body=f'''<div class="container"><section class="page-hero"><nav class="breadcrumb" aria-label="Caminho de navegação"><a href="index.html">MATRIZ</a><span>/</span><span>Exemplos</span></nav><h1>Conheça os<br><span class="accent">nossos projetos.</span></h1><p>Explore os quatro produtos em projetos e demonstrações. Filtre pelo que seu negócio precisa.</p><div class="actions"><a class="text-link" href="index.html#produtos">Comparar os produtos <span aria-hidden="true">↗</span></a></div></section><section class="case-section" id="projetos"><h2 class="visually-hidden">Exemplos por produto</h2><div class="filter-bar"><div class="filters" role="group" aria-label="Filtrar exemplos por produto">{filters}</div><p class="result-count" id="project-count" role="status" aria-live="polite">{len(cases)} exemplos</p></div><div class="project-list portfolio-projects" id="portfolio-projects">{''.join(case_tile(p) for p in cases)}</div><p class="scope-note">Os exemplos incluem interfaces, propostas visuais e demonstrações. Consulte os detalhes para conhecer o estágio de cada projeto.</p><details class="technical-details portfolio-technical" id="repertorio"><summary>Informações técnicas<span aria-hidden="true"></span></summary><div class="technical-content">{repertoire_rows()}</div></details></section></div>{cta()}'''
    write_page('repertoire.html','Exemplos dos quatro produtos — MATRIZ','Veja exemplos de sistema financeiro, sites, sistemas para negócios e planilhas de controle da MATRIZ.',body)

