    (ROOT/'.well-known').mkdir(exist_ok=True)
    (ROOT/'.well-known/security.txt').write_text(f'Contact: {BASE}contact.html\nContact: {LINKEDIN}\nCanonical: {BASE}.well-known/security.txt\nPreferred-Languages: pt-BR, en\nExpires: 2027-09-01T00:00:00Z\nPolicy: {BASE}security.html\n')
